%[text] # Spike Exploration
%[text] spikes.mlx illustrates specific issues in the analysis of extracellular recordings. This script builds on that to explore some additional parameter dependencies.
%[text:tableOfContents]{"heading":"Table of Contents"}
%[text] 
%[text] %[text:anchor:H_9BC26763] ## Setup Simulation
%[text] Simulation parameters
run('../startup'); % Make sure all toolboxes are on the path
defaults = [];
defaults.duration                  = 120;    % 2 min
defaults.stimulatorSamplingRate    = 1e3;     % e.g., Starstim (1 kHz)
defaults.currentResolution         = 1e-6;    % 1 muA
defaults.resistance                = 1;        % 1 mA -> 1 mV artifact
defaults.recordingSamplingRate     = 30e3;     % 30kHz
defaults.amplifierLinearRange            = 6.8e-3;   % Linear range of amplified 6.8 mV
defaults.adcNonlinearity           = 100;      % Piecewise linear
defaults.adcRange                  = 10e-3;     % Input range of the ADC.
defaults.adcBitDepth               = 16;       % Number of bits in the AD convertor
defaults.amplifierGain             = 20;       % Preamplifier gain
defaults.highPass                  = 0.01;     % High pass filter on the preamp. 
defaults.reproducible              = 2;       % Seed the RNG to get reproducible results

defaults.tacsAmplitude     = 120e-6;    % 120 muA
defaults.tacsFrequency     = 40;
%[text] Define the common neural signals
defaults.spikePeak                 = 60e-6;   % 60 muV
defaults.spikeRate                 = 100;      % 100 spk/s
defaults.poisson                           = true;     % Poisson spiking
defaults.fixNrSpikes               = true;     % Deviate from Poisson to get exact firing rate.
defaults.refractoryPeriod          = 1.5e-3;   % 1.5 ms
defaults.additive                  = 20e-6;    % Background activity/noise
defaults.pinkNoise                 = true;     % Pink background noise
defaults.synchrony                 = 0;        % Poisson random spikes, no relation with LFP
defaults.lfpAmplitude              = 0;        % No intrinsic oscillation
defaults.multiplicative            = 0;        % No multiplicative noise

%[text] Define the common parameters for artifact removal
%[text] 
ar = [];
ar.recordingSamplingRate = defaults.recordingSamplingRate; % Match to the recording
ar.segmentDuration       = 3;
ar.tacsFrequency         = defaults.tacsFrequency;
%[text] Setup the parameters for the artifact removal algorithms to explore.

fastr = [];
fastr.name = "FASTR";
fastr.options.slack = 5e-3;
fastr.options.nrSegsPerWindow = 10;
fastr.options.pcaNr = 2;
fastr.options.pcaVarExplained = Inf;
fastr.options.pcaNrSegsPerWindow = Inf;
fastr.options.referenceSegment = 1;


fbar= [];
fbar.name = "FBAR";
fbar.options.frequencyLimits = [-1 1];

rbar = [];
rbar.name = "RBAR";
rbar.options = [];

nop = [    ];
nop.name = "NOP";

%[text] Define the filter that extract signals in the "spike band":
lowCut                      = 500;  % high pass filter cut off
highCut                     = 7000; % Low pass filter cut off.
filterOrder                 = 3; % Filter order  (Butterworth)
%%
%[text] %[text:anchor:H_D38DE7B6] ## Frequency dependence
%[text] The spectral analysis (spikes.mlx) shows that the contamination of the spike band depends on the frequency of tACS. Here I investigate how different tACS frequencies affect the fraction of false negatives (for the current choices of neural signal, noise, and thresholds, the false positive rate is negligible).
methods  = {fastr,rbar,fbar};
A = artSim(defaults);
A.tacsAmplitude             = 120e-6;   % A->V artifact
nrMethods = numel(methods);
falsePositive = nan(2,nrTacsFreqs,nrMethods);
falseNegative = nan(2,nrTacsFreqs,nrMethods);
tacsFreqs = [2 5 10 20 40];
for m=1:nrMethods %[output:group:579f356d]
    for i=1:nrTacsFreqs
        A.tacsFrequency = tacsFreqs(i);
        ar.tacsFrequency = tacsFreqs(i);
        args = namedargs2cell(ar);
        A.sim;
        arResults= artifactRemoval(A.vContaminated,methods{m}, args{:},groundTruth=A.vTruth,vRecordTcs=A.vRecordTcs);      %[output:37358f15]
        [~,falsePositive(:,i,m),falseNegative(:,i,m)] = analyzeSpikes(A,arResults,lowCut=lowCut,highCut=highCut,filterOrder=filterOrder,threshold=threshold,spikeSortingMode=spikeSortingMode,axs=gobjects(4));         %[output:13da50d2]
    end
end %[output:group:579f356d]

%%
%[text] Generate a figure illustrating the stimuation frequency dependence.
[f,ax] = fig('Name','frequency','paperCols',2,'height',4,'nrRows',1,'nrCols',3);
methodNames = cellfun(@(x) (x.name),methods);
for method =1:nrMethods
    axes(ax(method)) %#ok<LAXES>
    hold on
    plot(tacsFreqs,falseNegative(:,:,method)','LineStyle','-');
    xlabel 'tACS frequency (Hz)'
    ylabel 'False Negatives (%)'
    set(gca,'XTick',tacsFreqs);
    title (methodNames(method))    
end
legend ('Sham','tACS','Location','south')

%%
%[text] ## Interactions
%[text] %[text:anchor:TMP_4a45] The simulations above show a non zero false negative rate after FASTR and that the tACS signal affects the results in the non-tACS trials (due to the shared voltage threshold and waveform clustering procedure). The percentages shown depend on the randomization; to quantify an average effect, I bootstrapped this.
A = artSim(defaults);
A.tacsAmplitude    = 120e-6;   % A->V artifact
A.tacsFrequency    = 40; % Example frequency
A.reproducible     = false; % Do not reset the RNG

ar.tacsFrequency = A.tacsFrequency;
args = namedargs2cell(ar);
nrBootstraps = 100;
falseNegFastr= nan(2,nrBootstraps);
% Use a parfor as this takes a while
parfor i=1:nrBootstraps        
      A.sim;
      arResults= artifactRemoval(A.vContaminated,fastr, args{:},groundTruth=A.vTruth,vRecordTcs=A.vRecordTcs);     
      [~,~,falseNegFastr(:,i)] = analyzeSpikes(A,arResults,lowCut=lowCut,highCut=highCut,filterOrder=filterOrder,threshold=threshold,spikeSortingMode=spikeSortingMode,axs=gobjects(4));            
end
%%
%[text] FIgure to show the results.
[~,axs] = fig('Name','Interactions','nrRows',1,'nrCols',2);
axes(axs(1))
mFalseNegFastr = mean(falseNegFastr,2,"omitmissing");
sdFalseNegFastr = std(falseNegFastr,0,2,"omitmissing");
bar(mFalseNegFastr);
hold on
errorbar(mFalseNegFastr,sdFalseNegFastr,'.')
set(gca,'XTick',1:2,'XTickLabel',{'Sham','tACS'});
ylabel ('False Negatives (%)');
axes(axs(2))
plot(falseNegFastr(2,:),falseNegFastr(1,:),'.')
xlabel 'tACS'
ylabel 'Sham'
r= corrcoef(falseNegFastr');
title (sprintf('Cross Contamination: r = %.2f',r(1,2)));

%%
%[text] ## tDCS
%[text] Repeat with tDCS and a heartbeat artifact.
A = artSim(defaults);
A.tacsAmplitude    = 0;    % A->V artifact
A.tdcsMean         = 1e-3;   % A->V artifact
ar.tacsFrequency  = 0;

A.zFun                      = @zHeartbeat;
A.zAmplitude                = 0.05;

[~,axs] = fig('Name',"tDCS",'paperCols',2,'height',12,'nrRows',2,'nrCols',2,'byColumn',false);    %[output:57f52db1]
A.sim;

arResults= artifactRemoval(A.vContaminated,nop, args{:},groundTruth=A.vTruth,vRecordTcs=A.vRecordTcs);      %[output:1d31aad3]
analyzeSpikes(A,arResults,phaseFromRaw = true,lowCut=lowCut,highCut=highCut,filterOrder=filterOrder,threshold=threshold,spikeSortingMode="ALL",axs=[axs(1:2) gobjects(1,2)]);             %[output:403cdd1d] %[output:57f52db1]

analyzeSpikes(A,arResults,phaseFromRaw = true,lowCut=lowCut,highCut=highCut,filterOrder=filterOrder,threshold=threshold,spikeSortingMode="MATCHSHAM",axs=[gobjects(1,2) axs(3:4)]);             %[output:0f98bab7] %[output:57f52db1]

%[text] The heartbeat artifact does not seem to affect the spike results. Not too surprising given that cardioballistic (and most other physiological artifacts) are low frequency events, far outside the spike band. 
%[text] 
